svg.script:
(function () {
  // Unités : mm, 1 px = 1 mm. Plan des champs en x = 40, axe en y = 180.
  var XC = 40, Y = 180, X1 = 120, X2 = 300, R2 = 50, R1_DEPART = 35, VG = 0.38;
  var $ = function (id) { return document.getElementById(id); };
  var svg = document.documentElement, r1 = R1_DEPART;
  function n(v) { return String(Math.round(v)).replace("-", "−"); }
  function seg(pts) { return "M" + pts.map(function (p) { return (XC + p[0]).toFixed(1) + " " + (Y - p[1]).toFixed(1); }).join(" L"); }
  function sur(p, q, x) { return p[1] + (q[1] - p[1]) * (x - p[0]) / (q[0] - p[0]); }
  function calcul(r) {
    var d2pupille = r / X1 > R2 / X2;                      // angle vu depuis le centre du plan des champs
    var xP = d2pupille ? X2 : X1, rP = d2pupille ? R2 : r, xL = d2pupille ? X1 : X2, rL = d2pupille ? r : R2;
    var t = xL / xP, k = Math.abs(1 - t);
    return { d2: d2pupille, xP: xP, rP: rP, PL: Math.max(0, (rL - rP * t) / k), M: rL / k, T: (rL + rP * t) / k };
  }
  function dessiner(r) {
    var c = calcul(r), xmax = 300;
    $("d1h").setAttribute("y1", Y - r - 32); $("d1h").setAttribute("y2", Y - r);
    $("d1b").setAttribute("y1", Y + r); $("d1b").setAttribute("y2", Y + r + 32);
    $("nd1").setAttribute("y", Y - r - 40);
    $("bouton").setAttribute("cy", Y - r); $("fleche").setAttribute("y", Y - r + 4.5);
    $("zone").setAttribute("y", Y - r - 30);
    $("rd1").setAttribute("y", Y - r - 60); $("rd1").textContent = c.d2 ? "lucarne" : "pupille";
    $("rd2").textContent = c.d2 ? "pupille" : "lucarne";
    $("rd1").style.fill = c.d2 ? "#aab2c0" : "#f3dcae"; $("rd2").style.fill = c.d2 ? "#f3dcae" : "#aab2c0";
    // faisceau de pleine ouverture issu du bord de PL (s'appuie sur les bords de la pupille)
    var A = [0, c.PL], h = [c.xP, c.rP], b = [c.xP, -c.rP];
    $("faisceau").setAttribute("d", seg([A, [xmax, sur(A, h, xmax)], [xmax, sur(A, b, xmax)]]) + " Z");
    var At = [0, c.T], bt = [c.xP, -c.rP];
    $("rayonT").setAttribute("d", seg([At, [xmax, sur(At, bt, xmax)]]));
    $("rayonM").setAttribute("d", seg([[0, c.M], [xmax, sur([0, c.M], [c.xP, 0], xmax)]]));
    [["pPL", "tPL", c.PL], ["pM", "tM", c.M], ["pT", "tT", c.T]].forEach(function (e) {
      $(e[0]).setAttribute("cy", Y - e[2]); $(e[1]).setAttribute("y", Y - e[2] + 5);
    });
    $("tPL").setAttribute("y", Y - c.PL + (c.PL < 14 ? 16 : 5));
    $("vT").setAttribute("r", VG * c.T); $("vM").setAttribute("r", VG * c.M); $("vPL").setAttribute("r", VG * c.PL);
    $("mesures").textContent = "Demi-champs : PL = " + n(c.PL) + " mm · M = " + n(c.M) + " mm · T = " + n(c.T) + " mm";
    $("bilan").textContent = c.PL < 0.5 ? "Plus de pleine lumière : tout le champ est en contour"
      : (c.d2 ? "[D₂] est la pupille, [D₁] la lucarne" : "[D₁] est devenu la pupille, [D₂] la lucarne");
    return c;
  }
  var actif = false;
  function versSVG(e) { var p = svg.createSVGPoint(); p.x = e.clientX; p.y = e.clientY; return p.matrixTransform(svg.getScreenCTM().inverse()); }
  var poignee = $("poignee");
  poignee.addEventListener("pointerdown", function (e) { actif = true; $("aide").setAttribute("visibility", "hidden"); poignee.setPointerCapture(e.pointerId); e.preventDefault(); });
  poignee.addEventListener("pointermove", function (e) {
    if (!actif) return;
    r1 = Math.max(8, Math.min(58, Y - versSVG(e).y));
    dessiner(r1);
  });
  function lacher() { if (actif) verifierDefi(); actif = false; }
  poignee.addEventListener("pointerup", lacher); poignee.addEventListener("pointercancel", lacher);
  $("rejouer").addEventListener("click", function () { r1 = R1_DEPART; defi = -1; $("defi").setAttribute("visibility", "hidden"); dessiner(r1); });

  var DEFIS = [
    { texte: "un demi-champ PL de 40 mm", cible: 44, ok: function (c) { return c.d2 && Math.abs(c.PL - 40) < 3; } },
    { texte: "plus de pleine lumière (PL = 0)", cible: 20, ok: function (c) { return c.PL < 2; } },
    { texte: "[D₁] devient la pupille", cible: 14, ok: function (c) { return !c.d2; } }
  ];
  var defi = -1;
  function afficherDefi() {
    $("defi").setAttribute("visibility", "visible"); $("defifond").setAttribute("stroke", "#d9b26f");
    $("defi1").textContent = "🎯 Défi " + (defi + 1) + "/" + DEFIS.length + " : règle [D₁] pour avoir";
    $("defi2").textContent = DEFIS[defi].texte;
  }
  function verifierDefi() {
    if (defi < 0) return;
    if (!DEFIS[defi].ok(calcul(r1))) return;
    r1 = DEFIS[defi].cible; dessiner(r1);
    $("defifond").setAttribute("stroke", "#5fd08a"); $("defi1").textContent = "✓ Bravo !";
    var fini = defi === DEFIS.length - 1;
    $("defi2").textContent = fini ? "Tous les défis sont réussis 🎉" : "Défi suivant dans un instant…";
    var suivant = defi + 1; defi = fini ? -1 : -2;
    if (!fini) setTimeout(function () { defi = suivant; afficherDefi(); }, 1600);
  }
  $("bdefi").addEventListener("click", function () { $("aide").setAttribute("visibility", "visible"); defi = 0; afficherDefi(); });
  dessiner(r1);
})();
